# -*- coding: utf-8 -*-
"""Rest, release and settled affairs: QUI / QUIET / QUIT."""
import json
from pathlib import Path
from lesson_authoring import entry as E
H=[['拉丁 quiēs、quiēscere、quiētus','休息；安静下来；安宁、免于负担的']]
Q=H+[['古法语 quiet / quiete → 中古英语 → quiet','安宁、休息 → 安静；安宁']]
QT=H+[['中世纪拉丁 quiētus → 古法语 quitte / quitter','免除负担的 → 解除、离开'],['中古英语 → quit','退出、停止；摆脱']]
AC=H+[['中世纪拉丁 acquitāre；古法语 aquiter','解除债务或负担'],['中古英语 → acquit','免除责任、宣告无罪；履行自己的角色']]
AQ=H+[['拉丁 ad- + quiēscere → acquiēscere；法语 acquiescer','安顿下来、接受'],['英语 acquiesce','不再反对而接受；默许']]
QC=H+[['拉丁 quiēscēns → 英语 quiescent','休息中的 → 静止、暂不活跃的']]
def D(h,a,b):return h+[[a,b]]
W=[
E('quiet','/ˈkwaɪət/','安静的；平静的；清静；使安静','不被噪声、忙乱或冲突搅动，事情安稳下来，就是 quiet 的共同画面。','拉丁 quiēs、quiētus，经法语 quiete、quiet 等形式传入；名词与形容词有相连但不同的传入形式。',Q,'a quiet room 是安静房间，a quiet week 可能只是事情少，a quiet person 常是不多话。quiet 也能作动词，说使担忧或人群平静。','keep quiet；peace and quiet；a quiet day；quiet fears。','silent 更接近无声；quiet 可以仍有轻微声音。quiet 两音节，quite 一个音节。',('Please keep quiet while the others are working.','别人工作时请保持安静。'),('Business was quiet this week.','这周生意比较清淡。'),('The explanation helped quiet their fears.','解释帮助平息了他们的担忧。'),sources=['https://www.etymonline.com/word/quiet']),
E('quit','/kwɪt/','停止；辞去；退出；摆脱','原先背着一项义务或关系，后来不再被它牵住；“解除负担”的历史走向了离开与停止。','古法语 quitte、quitter，接中世纪拉丁 quiētus“免于负担的”；不是现代英语 quiet 随手删掉字母。',QT,'quit a job 是辞职，quit doing something 是停止做某事。美式过去式常仍用 quit；quitted 也见于某些较正式或英式用法。','quit a job；quit doing；quit the team；be quit of〔较旧〕。','pause 只是暂时停；quit 通常表示退出或终止，而不是按一下暂停键。',('She quit her job to start a small business.','她辞去工作，开始经营一家小企业。'),('He quit playing when the rain became too heavy.','雨下得太大后，他停止了比赛。'),sources=['https://en.wiktionary.org/wiki/quit#English']),
E('quite','/kwaɪt/','相当；很；完全；确实','早期是“彻底、完全”，后来也可弱化成“相当”。它的力度要跟着后面的词、语气和地区习惯一起判断。','中古英语 quit / quite“免除、完全清楚”的副词用法，接 quit 的历史支线。',QT[:-1]+[['中古英语 quit / quite 的副词用法 → quite','完全、彻底 → 也可表示相当']],'quite impossible 通常是完全不可能；quite good 在英式语境可只是相当不错，在别的语气下也能更强。quite a few 是不少，不是很少。','quite sure；quite good；quite impossible；quite a few。','quiet 是安静，quite 是程度副词。不要把 quite 在所有句子中固定译成“非常”或“有点”。',('The room is quite small, but it is comfortable.','房间相当小，不过很舒服。'),('I am quite sure I left the keys on the table.','我很确定把钥匙放在桌上了。'),('Quite a few people stayed after the talk.','演讲结束后，有不少人留了下来。'),sources=['https://www.etymonline.com/word/quite']),
E('quietly','/ˈkwaɪətli/','轻声地；安静地；不声张地','动作不制造大动静，声音低，或事情进行得不引人注意，都可以用 quietly。','quiet + -ly；中古英语已有 quietely 等形式。',D(Q,'英语 quiet + -ly → quietly','安静的 → 安静地、不声张地'),'speak quietly 说音量；quietly resign 则可以说低调辞职，未必全程没有讲话。也可说 quietly confident，表示有信心但不张扬。','speak quietly；leave quietly；quietly confident。','silently 强调没有声音；quietly 可以有轻声交谈，也可强调不公开张扬。',('She closed the door quietly so as not to wake the baby.','她轻轻关上门，以免吵醒婴儿。'),('The team was quietly confident about the result.','团队对结果有信心，但并不张扬。')),
E('quieter','英 /ˈkwaɪətə/；美 /ˈkwaɪətər/','更安静的；使人安静者〔罕见名词〕','两个地方相比，一个的声响、忙乱或活动更少，就把 quiet 放到比较级 quieter。','最常用是 quiet + 比较级 -er；另有 quiet 动词 + 施事 -er 的少见名词，同形但功能不同。',D(Q,'英语 quiet + -er → quieter','更安静的；另一名词用法是使安静者'),'日常首先认比较级，如 a quieter room、quieter than before。不要因词典收了少见的人物名词，就错过最常用的“更安静”。','quieter than；a quieter street；become quieter。','quietest 是最安静的；quieter 是比较起来更安静，不要求在所有选项中最安静。',('Can we move to a quieter table?','我们能换到一张更安静位置的桌子吗？'),('The street is much quieter after midnight.','午夜后，这条街安静多了。')),
E('quietness','/ˈkwaɪətnəs/','安静；平静；不张扬的特点','把 quiet 的感觉单独拿出来说：周围没什么动静，或一个人的表达沉静不张扬。','quiet + -ness；中古英语已有对应形式。',D(Q,'英语 quiet + -ness → quietness','安静的 → 安静状态、沉静特点'),'可以说地方的清静，也可说一个人的沉静。通常不需要数成一个个 quietnesses。','the quietness of the room；a quietness in her manner。','silence 侧重无声；quietness 更宽，能带平稳、不热闹的感觉。',('I enjoyed the quietness of the house in the early morning.','我喜欢清晨屋子里的安静。'),('There was a quietness in his manner that made people feel at ease.','他的举止有一种让人放松的沉静。')),
E('quieten','/ˈkwaɪətən/','使安静；安静下来〔较多见于英式英语〕','给 quiet 加一个表示变化的 -en，让状态变成动作：把喧闹降下来，或自己慢慢平静。','quiet + -en；英语动词派生。',D(Q,'英语 quiet + -en → quieten','安静 → 变得或使之安静'),'可及物 quieten the crowd，也可不及物 the room quietened。quieten down 很常见；美式语境往往用 quiet down。','quieten down；quieten a crowd；quieten fears。','quiet 本身也可作动词；quieten 是另一种常见于英式的形式，不另指一种特殊安静。',('The class quietened down when the teacher began to speak.','老师开始讲话时，全班安静了下来。'),('The announcement did little to quieten public concern.','这则公告没能让公众的担忧缓解多少。')),
E('quietude','英 /ˈkwaɪətjuːd/；美 /ˈkwaɪətuːd/','宁静；静谧〔书面、文学〕','比普通的“声音小”更像一种笼罩空间或内心的宁静，适合描写庭院、清晨或沉静时刻。','后期拉丁 quiētūdō，经法语 quiétude 借入；不是现代英语把 quiet 与随意字母拼接。',[H[0],['后期拉丁 quiētūdō → 法语 quiétude → 英语 quietude','宁静的状态']],'与 quietness 意义相近，但语气更文学、更郑重。日常要求别人别说话，一般不用这个名词。','the quietude of the garden；a moment of quietude。','quietude 比 quiet 或 quietness 更书面；不必硬说成绝对无声，宁静中也可以有自然声响。',('She found quietude in the garden at dawn.','她在黎明的花园里感受到了宁静。'),('The poem captures the quietude of a winter morning.','诗歌写出了冬日清晨的静谧。')),
]
W.extend([
E('acquit','/əˈkwɪt/','宣告无罪；履行、表现〔acquit oneself〕','原来是把人从债务、指控或责任负担中解脱出来；后来最常见的是法庭上的无罪裁决。','中世纪拉丁 acquitāre、古法语 aquiter，接 ad- 与 quitare“解除”；更早关联 quiētus。',AC,'acquit someone of a charge 是裁定某项指控不成立；这不同于声称已证明世间一切事实。acquit oneself well 则表示完成自己的角色、表现得好。','acquit someone of；be acquitted；acquit oneself well。','convict 是定罪；acquit 是宣告无罪。acquit oneself 在日常评价表现时，不是给自己作司法裁决。',('The jury acquitted her of the charge.','陪审团裁定她不犯所控罪名。'),('Despite his inexperience, he acquitted himself well in the debate.','尽管经验不足，他在辩论中表现得很好。'),sources=['https://en.wiktionary.org/wiki/acquit#English','https://www.law.cornell.edu/wex/acquittal']),
E('acquittal','/əˈkwɪtəl/','无罪裁决；宣告无罪','把 acquit 这个裁决动作变成结果或事件：被告在所控罪名上得到无罪裁决。','acquit + -al；英语动作、结果名词。',D(AC,'英语 acquit + -al → acquittal','宣告无罪 → 无罪裁决'),'常在庭审报道中出现。它说的是法律裁决，不能机械扩大为“所有怀疑都已通过新证据彻底证明不存在”。','an acquittal on all counts；a verdict of acquittal。','acquittal 与 conviction 是相反的裁决结果；dismissal 还可涉及案件或指控因其他理由被撤销，不能无条件互换。',('The trial ended in an acquittal.','审判以无罪裁决结束。'),('Her family welcomed the acquittal on all charges.','家人对所有指控均获无罪裁决表示欣慰。'),sources=['https://www.law.cornell.edu/wex/acquittal','https://en.wiktionary.org/wiki/acquittal#English']),
E('acquiesce','/ˌækwiˈes/','默许；勉强接受；不再反对','原来心里或行动上还在抗拒，后来让争执静下来，接受眼前安排；不一定满心赞成。','拉丁 ad- + quiēscere → acquiēscere，经法语 acquiescer 或拉丁借入。',AQ,'常用 acquiesce in a decision 或 acquiesce to a demand。它描述不再反对而接受的行为，不能倒过来说所有沉默都表示接受。','acquiesce in；acquiesce to；reluctantly acquiesce。','agree 可以热情赞同；acquiesce 常带被动、勉强或不再抗争的意味。',('She reluctantly acquiesced to the change in schedule.','她勉强接受了日程的变更。'),('He refused to acquiesce in a decision he considered unfair.','他认为决定不公平，拒绝默默接受。')),
E('acquiescence','/ˌækwiˈesəns/','默许；被动接受；顺从','不反对、顺着安排走的状态被拿出来当作一个整体说，就是 acquiescence。','法语 acquiescence 借入，最终接拉丁 acquiēscere 词族；现代与 acquiesce 相对应。',[H[0],['拉丁 acquiēscere 词族 → 法语 acquiescence','安顿、接受 → 默许'],['英语 acquiescence','不再反对的接受状态']],'常与 reluctant、passive 连用，突出处于接受状态，但不是强烈支持。法律语境可能有更专门的含义，日常不把沉默直接当成已经许可。','reluctant acquiescence；passive acquiescence；acquiescence in。','approval 是认可、赞同；acquiescence 可以只是容忍或不再抵抗，两者力度不同。',('They mistook her silence for acquiescence.','他们误把她的沉默当成了默许。'),('The plan went ahead with his reluctant acquiescence.','他虽不情愿，还是接受了，计划于是继续推进。')),
E('acquiescent','/ˌækwiˈesənt/','顺从的；愿意默许的；不加反对的','这个形容词描述一种容易接受别人安排、不主动抵抗的态度，而不是一次明确说出的“我完全赞成”。','拉丁 acquiēscēns，是 acquiēscere 的现在分词；借入英语，不只靠英语动词加 -ent 解释历史。',[H[0],['拉丁 acquiēscere → acquiēscēns → 英语 acquiescent','安顿、接受 → 不反对、顺从的']],'常含被动接受的语感；在某些评论中甚至批评过于顺从。配 to 可说对某种要求顺从。','an acquiescent attitude；acquiescent to demands。','cooperative 强调愿意合作；acquiescent 更强调不反对，未必积极参与。',('He was unusually acquiescent during the meeting.','他在会上异常顺从，几乎没有提出异议。'),('The committee was criticised for being too acquiescent to outside pressure.','委员会被批评对外部压力过于顺从。'),sources=['https://www.merriam-webster.com/dictionary/acquiescent','https://en.wiktionary.org/wiki/acquiescent#English']),
E('acquittance','/əˈkwɪtəns/','清偿；解除债务或责任；收讫凭证〔较旧、法律〕','债还清、责任解除后，需要有个结果或凭证说明“这笔账结了”，这就是它保留的老画面。','盎格鲁法语 acquitance、古法语 aquitance，接 acquiter；比 acquittal 保留更明显的历史债务用法。',[H[0],['古法语 aquiter → aquitance；盎格鲁法语 acquitance','解除负担、偿清 → 清偿或解除凭证'],['英语 acquittance','清偿；责任解除；收据等凭证']],'现代日常较少用，阅读旧账簿、契约或文学时更容易碰到。它也曾表示解除指控，但现代庭审常见的是 acquittal。','an acquittance for payment；a written acquittance。','receipt 是现代常用收据；acquittance 带较旧、正式的债务解除色彩。',('The archive contains an acquittance for the final payment.','档案中保存着最后一笔付款的收讫凭证。'),('The letter requested a written acquittance after the debt was settled.','信中要求在债务结清后出具书面解除凭证。')),
E('coy','/kɔɪ/','腼腆含蓄的；故作羞怯的；不肯明说的','从安静、含蓄，走到话只说一半、态度不完全亮出来；今天常带有刻意保留的感觉。','拉丁 quiētus，经古法语 coi / quei“安静的”进入中古英语 coy；与 quiet 是不同借入路线。',[H[0],['古法语 coi / quei → 中古英语 coy','安静、温和 → 腼腆含蓄'],['现代英语 coy','故作羞怯；对某事不肯明说']],'a coy smile 是含蓄、可能带故作羞怯的笑；be coy about plans 是不肯透露计划。描述他人时可能带说话者的评价，而非客观判定对方真实想法。','be coy about；a coy smile；remain coy。','shy 可以是真实害羞；coy 常让人感觉有所保留或做出含蓄姿态，不能总当成温和同义词。',('The company remained coy about its next product.','公司对下一款产品仍不肯多说。'),('She gave a coy smile and changed the subject.','她含蓄地一笑，换了话题。'),sources=['https://www.etymonline.com/word/coy']),
E('disquiet','/dɪsˈkwaɪət/','不安；忧虑；使不安','原本安静的内心被搅动了，虽然外面可能一声不响，心里已经没有 quiet。','dis- 表否定或扰乱 + quiet；英语形成动词与名词。',D(Q,'英语 dis- + quiet → disquiet','破坏安宁 → 使不安；不安'),'既可作名词 public disquiet，也可作动词 disquiet someone，语气比日常的 worry 更书面。重点是心里的不安，不一定有明显噪声。','public disquiet；a sense of disquiet；disquiet someone。','noise 是外部声响；disquiet 可以发生在完全安静的房间里，描写心理或社会上的不安。',('The sudden change caused disquiet among the staff.','突然的变化让员工们感到不安。'),('Something in his answer disquieted her.','他的回答中有些东西让她不安。')),
])
W.extend([
E('requiem','/ˈrekwiəm/','安魂弥撒；安魂曲；悼念之作','为逝者祈求安息，开头那个表示“安息”的拉丁词，后来成了整套仪式或音乐作品的名字。','拉丁 requiem 是 requiēs“休息、安息”的宾格，取自传统安魂弥撒开头；re- 与 quiēs 相连。',[H[0],['拉丁 requiēs → 宾格 requiem','休息、安息'],['礼仪开头用词 → 英语 requiem','安魂弥撒；为其创作的音乐；悼念作品']],'可以说一场宗教仪式，也可以说供演出的合唱、管弦乐作品。引申为 requiem for a lost way of life，表示对消逝生活方式的悼念。','a requiem mass；perform a requiem；a requiem for。','elegy 通常是哀歌或挽诗；requiem 有祈求安息的礼仪与音乐背景。requiem shark 中的 requiem 通常接法语 requin，是另一来源。',('The choir performed a requiem in memory of the victims.','合唱团演出了一部安魂曲，纪念遇难者。'),('The film feels like a requiem for a disappearing village.','这部电影像是为一个即将消失的村庄写下的挽歌。')),
E('quiescent','/kwiˈesənt/，也读 /kwaɪˈesənt/','暂时不活跃的；静止的；休眠的','机器暂时没有动作，过程暂时没有明显活动，像是进入休息状态；它强调活动少，不只是声音小。','拉丁 quiēscēns“正在休息的”，来自 quiēscere；学术借词。',QC,'用于系统、过程、细胞等较正式语境。静止期细胞通常指暂不分裂的状态，仍可进行代谢，不能理解成死细胞。','a quiescent period；quiescent cells；remain quiescent。','quiet 常描述声音或气氛；quiescent 更常描述活动状态。dormant 也可指休眠，两者需看专业语境。',('The system remained quiescent until a new request arrived.','系统一直没有活动，直到新的请求到来。'),('The researchers distinguished quiescent cells from dead cells.','研究人员区分了静止期细胞与死细胞。')),
E('unquiet','/ʌnˈkwaɪət/','不安的；不平静的；喧闹的〔多为书面语〕','在 quiet 前加否定，把安宁拿掉：可能是人声纷乱，也可能是心里翻来覆去、不能安定。','un- 不 + quiet；英语构词。',D(Q,'英语 un- + quiet → unquiet','不安静的 → 不安、动荡的'),'常见于 a restless or unquiet mind 一类文学描写；普通口语说房间吵，多用 noisy，说人焦虑多用 anxious。','an unquiet mind；unquiet times；unquiet sleep。','unquiet 不只等于 loud。一个人一言不发，也可能有 an unquiet mind。',('He lay awake with an unquiet mind.','他心绪不宁，醒着躺在床上。'),('The novel is set in unquiet times.','小说的背景是一个动荡不安的年代。')),
E('quietus','/kwaɪˈiːtəs/','终结；了结；死亡〔文学〕','旧账结清，账本写明“此人已经清讫”；这个彻底结账的画面后来被用来讲事情的终结，甚至生命的终结。','来自中世纪拉丁 quietus est“已获解除、已清讫”的缩略用法；其中 quietus 接 quiētus。',[H[0],['中世纪拉丁 quietus est','账项清讫、责任解除'],['英语 quietus','清偿、了结 → 终结；文学中的死亡']],'现代较常在书面固定搭配 put a quietus on 中出现，意思是把某事彻底压下或终止。它不是 quiet 的普通名词形式。','put a quietus on speculation；give a quietus to a dispute。','quietness 是安静状态；quietus 是结清、终结，虽然同源，意义已经分开。',('The official announcement put a quietus on the speculation.','官方公告让猜测平息下来。'),('In the poem, quietus is used as a literary word for death.','在诗中，quietus 被用作表示死亡的文学词。'),sources=['https://www.etymonline.com/word/quietus']),
E('quiescence','/kwiˈesəns/，也读 /kwaɪˈesəns/','静止状态；暂不活跃；静止期','把 quiescent 的状态当作一个阶段来谈：过程暂时平静，细胞暂时没有进入分裂。','可按 quiescent 对应 -ence 理解；词源记录也列拉丁 quiēscentia 的借入解释，两条分析不强行排成先后。',[H[0],['拉丁 quiēscentia；或英语 quiescent 对应 -ence','休息、不活跃的状态'],['英语 quiescence','静止；暂不活跃状态']],'在生物学中，许多细胞能从静止期重新进入细胞周期；但能否恢复要看具体细胞与条件。quiescence 不等于毫无代谢，也不等于永久停止一切功能。','a period of quiescence；cellular quiescence；return to quiescence。','inactivity 是更普通的不活跃；quiescence 更常用于过程或专业状态，不能只靠词根替代专业定义。',('The region experienced a long period of political quiescence.','这个地区经历了一段很长的政治平静期。'),('The study examined how cells enter and leave quiescence.','研究考察了细胞如何进入和退出静止期。')),
E('requiescat','/ˌrekwiˈeskæt/','为逝者安息而作的祷文；悼念诗文〔少见〕','一句“愿他或她安息”，被拿来命名这类祷文或悼念文字。重点是安息的祝愿。','拉丁 requiēscat“愿其安息”，是 requiēscere 的虚拟式；常见于 requiescat in pace。',[H[0],['拉丁 re- + quiēscere → requiēscere','休息、安息'],['拉丁 requiēscat → 英语名词 requiescat','愿其安息 → 安息祷文、悼念作品']],'主要在宗教、文学或作品标题中碰到。拉丁语中的动词形式，借入英语后可以当作一篇作品或祷文的名称。','a requiescat for；a poem titled Requiescat。','requiem 常指弥撒或音乐作品；requiescat 更直接保留“愿其安息”的祈愿形式，使用范围较窄。',('The anthology includes a short requiescat for a lost friend.','诗集中收录了一首悼念亡友的短诗。'),('The scholar explained the Latin phrase behind the title Requiescat.','学者解释了《愿其安息》这一标题背后的拉丁语表达。')),
E('inquietude','英 /ɪnˈkwaɪətjuːd/；美 /ɪnˈkwaɪətuːd/','不安；忧虑；心神不宁〔书面、文学〕','quietude 是宁静；前面加上否定，人虽坐着，心里却像一直有东西翻动，无法安稳。','拉丁 inquiētūdō，来自 in- 不 + quiētus；法语 inquiétude 与英语此词属于这条词族。',[H[0],['拉丁 in- + quiētus → inquiētūdō','不安宁 → 不安的状态'],['英语 inquietude','心神不宁；忧虑']],'适合文学描写或正式议论，日常通常说 unease、worry 或 anxiety。它不是一个可以单独用来诊断人的医疗标签。','a sense of inquietude；growing inquietude。','in- 在这里是否定，不是“在里面”。quietude 与 inquietude 词形相近，情绪方向正相反。',('A sense of inquietude spread through the waiting crowd.','一阵不安在人群中蔓延，大家仍在等待。'),('The letter filled her with an inquietude she could not explain.','那封信让她充满一种说不清的不安。'),sources=['https://www.merriam-webster.com/dictionary/inquietude']),
])
for item in W:
 if item['word'] in ('quiescent','quiescence'):
  item['sources'] += ['https://pmc.ncbi.nlm.nih.gov/articles/PMC1393757/','https://pmc.ncbi.nlm.nih.gov/articles/PMC2958657/']
ROOT=dict(id='C1190',meaning='休息、安宁；从负担中解脱',core='QUI / QUIET / QUIT = REST, BE AT PEACE',image='先想一个人卸下重担，终于能坐下休息。身体安静下来是 quiet；义务或牵绊被解除，走向 quit、acquit；争执安顿下来，走向 acquiesce。',intro='拉丁 quiēs 是休息，quiēscere 是休息、安定下来，quiētus 是安宁、没有负担的。词族有两条特别有用的线：声音和活动平静下来；债务、责任或牵绊得到解除。后者帮助理解 quit 为什么不只是“安静”。',forms='quiet、quit、quite 分别常读两个音节、短元音一个音节、双元音一个音节；拼写相近不能互换。coy 经古法语 coi 进入，外形变化很大。acquiesce 的 -quiesc- 保留“安顿下来”的拉丁动词词干。',branches=[['安静与不安','quiet, quietly, quieter, quietness, quieten, quietude, unquiet, disquiet, inquietude'],['解除牵绊、完成与退出','quit, quite, acquit, acquittal, acquittance, quietus'],['顺从与含蓄','acquiesce, acquiescence, acquiescent, coy'],['暂时静止与安息','quiescent, quiescence, requiem, requiescat']],contrasts='quit 不是 quiet 的缩写；quite 不是“很安静”。acquiesce 表示接受或不再反对，不能据此把所有沉默都当成同意。quiescent 指不活跃，不能直接等于已经死亡。',practice='The room became quiet, but she was not quite ready to acquiesce. She would rather quit the project than accept the new terms.\n\n房间安静下来，可她还没准备好接受安排。她宁愿退出项目，也不愿接受新的条件。',words=[w['word'] for w in W])
